use super::*;

/// Whether PHP 8.5's `date_create_from_format()` accepts each format and
/// string, generated by running it.
const FROM_FORMAT_CASES: &[(&str, &str, bool)] = &[
    ("Y-m-d", "2020-10-12", true),
    ("Y-m-d", "2022/02/20", false),
    ("Foobar", "2022-02-20", false),
    ("Y-m-d H:i:s", "2020-10-12 10:11:12", true),
    ("Y-m-d H:i", "2020-10-12 1:11", true),
    ("d/m/Y", "1/2/2020", true),
    ("Y-m-d", "2020-10-12 extra", false),
    ("Y-m-d+", "2020-10-12 extra", true),
    ("Y-m-d", "2020-10", false),
    ("!d", "15", true),
    ("D, d M Y", "Mon, 15 Aug 2005", true),
    ("l jS F Y", "Monday 15th August 2005", true),
    ("M d Y", "Foo 12 2020", false),
    ("H:i a", "10:30 pm", true),
    ("a H", "pm 10", false),
    ("Y", "12345", false),
    ("Y", "20", true),
    ("y-m", "20-1", true),
    ("Y#m#d", "2020;10;12", true),
    ("Y?m?d", "2020x10x12", true),
    ("Y\\Tm", "2020T10", true),
    ("Y-m-d u", "2020-10-12 123", true),
    ("Y-m-d v", "2020-10-12 12", true),
    ("Y-m-d|", "2020-10-12", true),
    ("H:i", "10:5", false),
    ("Ymd", "20201012", true),
    ("Y-m-d", "2020-13-45", true),
    ("", "", true),
    ("j.n.Y", "5.6.2020", true),
    ("Y-m-d", "foo", false),
    ("d", "x5", false),
    ("jS", "1st", true),
    ("jS", "1xx", false),
];

/// Every one of these is accepted by PHP.
const DATE_CREATE_VALID: &[&str] = &[
    "2020-10-12",
    "now",
    "Today",
    "",
    "2020-10-12T10:11:12",
    "2020-10-12 10:11",
    "2020-10-12T10:11:12.5+02:00",
    "2020-10-12T10:11:12Z",
    "2020-02-31",
    "tomorrow",
    "2020-10-12T10:11:12+0200",
];

#[test]
fn parses_from_format_like_php() {
    for (format, datetime, accepted) in FROM_FORMAT_CASES {
        assert_eq!(
            parse_from_format(format.as_bytes(), datetime.as_bytes()),
            Some(*accepted),
            "date_create_from_format({format:?}, {datetime:?})"
        );
    }
}

#[test]
fn leaves_unread_fields_undecided() {
    assert_eq!(parse_from_format(b"Y-m-d e", b"2020-10-12 UTC"), None);
    assert_eq!(parse_from_format(b"Y", b"-2020"), None);
}

#[test]
fn recognises_valid_free_form_dates() {
    for datetime in DATE_CREATE_VALID {
        assert!(certainly_valid(datetime), "date_create({datetime:?})");
    }
    for datetime in [
        "foo",
        "202/20",
        "2020-10-12T25:00",
        "2020-13-01",
        "next monday",
        "4 qm",
    ] {
        assert!(!certainly_valid(datetime), "date_create({datetime:?})");
    }
}

#[test]
fn types_strtotime_by_spelling() {
    let ty = |datetime: &str, has_base: bool| {
        strtotime(&PhpType::literal_string_value(datetime), has_base).map(|ty| ty.to_string())
    };
    assert_eq!(ty("now", false).as_deref(), Some("int<1, max>"));
    assert_eq!(ty("now", true).as_deref(), Some("int"));
    assert_eq!(ty("+2 days", false).as_deref(), Some("int"));
    assert_eq!(
        ty("1990-01-01 12:00:00 UTC", false).as_deref(),
        Some("int<1, max>")
    );
    assert_eq!(ty("1969-12-31 12:00:00 UTC", false).as_deref(), Some("int"));
    assert_eq!(ty("", false).as_deref(), Some("false"));
    assert_eq!(ty("4 qm", false), None);
}
